/// <summary>
/// Main method to initiate class
/// </summary>
/// <param name = "_args">Args reference</param>
public static void main(Args _args)
{
    METSalesOrderFinalizationAutomateController controller      = METSalesOrderFinalizationAutomateController::construct();

    controller.startOperation();
}

/// <summary>
/// Construct class to create instance
/// </summary>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>Controller class</returns>
public static METSalesOrderFinalizationAutomateController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    return new METSalesOrderFinalizationAutomateController(identifierStr(METSalesOrderFinalizationAutomateService), methodStr(METSalesOrderFinalizationAutomateService, executeOperation), _executionMode);
}

